package com.ecole.gestion_scolaire.hr.entity; import com.ecole.gestion_scolaire.school.entity.*; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="teacher_rate") public class TeacherRate { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="teacher_id") private Teacher teacher; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="school_year_id") private SchoolYear schoolYear; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="class_group_id") private ClassGroup classGroup; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="subject_id") private Subject subject; @Column(name="work_type",nullable=false,length=40) private String workType; @Column(name="hourly_rate",nullable=false,precision=14,scale=2) private BigDecimal hourlyRate; @Column(name="effective_from",nullable=false) private LocalDate effectiveFrom; @Column(name="effective_until") private LocalDate effectiveUntil; @Column(nullable=false) private boolean active; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; @PrePersist void pre(){if(createdAt==null)createdAt=OffsetDateTime.now();} public Long getId(){return id;} public Teacher getTeacher(){return teacher;} public void setTeacher(Teacher v){teacher=v;} public SchoolYear getSchoolYear(){return schoolYear;} public void setSchoolYear(SchoolYear v){schoolYear=v;} public ClassGroup getClassGroup(){return classGroup;} public void setClassGroup(ClassGroup v){classGroup=v;} public Subject getSubject(){return subject;} public void setSubject(Subject v){subject=v;} public String getWorkType(){return workType;} public void setWorkType(String v){workType=v;} public BigDecimal getHourlyRate(){return hourlyRate;} public void setHourlyRate(BigDecimal v){hourlyRate=v;} public LocalDate getEffectiveFrom(){return effectiveFrom;} public void setEffectiveFrom(LocalDate v){effectiveFrom=v;} public LocalDate getEffectiveUntil(){return effectiveUntil;} public void setEffectiveUntil(LocalDate v){effectiveUntil=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} }
